trait Scorer {
    const NAME: &'static str;

    fn score(&self, word: &str) -> u32;

    fn total(&self, words: &[&str]) -> u32 {
        words.iter().map(|w| self.score(w)).sum()
    }
}

struct LengthScorer;

struct VowelScorer {
    bonus: u32,
}

struct LetterScorer;

impl Scorer for LengthScorer {
    const NAME: &'static str = "length";
    fn score(&self, word: &str) -> u32 {
        word.chars().count() as u32
    }
}

impl Scorer for VowelScorer {
    const NAME: &'static str = "vowels";
    fn score(&self, word: &str) -> u32 {
        word.chars()
            .filter(|c| c.is_alphabetic())
            .map(|c| if "aeiouAEIOU".contains(c) { self.bonus } else { 1 })
            .sum()
    }
}

impl Scorer for LetterScorer {
    const NAME: &'static str = "letters";
    fn score(&self, word: &str) -> u32 {
        word.chars()
            .map(|c| match c.to_ascii_uppercase() {
                'A' | 'E' | 'I' | 'L' | 'N' | 'O' | 'R' | 'S' | 'T' | 'U' => 1,
                'D' | 'G' => 2,
                'B' | 'C' | 'M' | 'P' => 3,
                'F' | 'H' | 'V' | 'W' | 'Y' => 4,
                'K' => 5,
                'J' | 'X' => 8,
                'Q' | 'Z' => 10,
                _ => 0,
            })
            .sum()
    }
}

fn best_word<'a, S: Scorer>(scorer: &S, words: &[&'a str]) -> Option<&'a str> {
    let mut best: Option<&'a str> = None;
    let mut best_score = 0;
    for &w in words {
        let s = scorer.score(w);
        if best.is_none() || s > best_score {
            best = Some(w);
            best_score = s;
        }
    }
    best
}

fn describe<S: Scorer>(scorer: &S, word: &str) -> String {
    format!("{}: {} scores {}", S::NAME, word, scorer.score(word))
}

unitTests:
test("each scorer", || {
    check_eq(LengthScorer.score("crab"), 4);
    check_eq(LengthScorer.score("été"), 3);
    check_eq(VowelScorer { bonus: 3 }.score("Ocean!"), 3 + 1 + 3 + 3 + 1);
    check_eq(LetterScorer.score("Quiz"), 10 + 1 + 1 + 10);
    check_eq(LetterScorer.score("jam-jar"), 8 + 1 + 3 + 0 + 8 + 1 + 1);
});

test("the default total", || {
    check_eq(LengthScorer.total(&["a", "bb", "ccc"]), 6);
    check_eq(LetterScorer.total(&[]), 0);
});

test("best words with any scorer", || {
    let words = ["zoo", "audio", "strengths", "quiz"];
    check_eq(best_word(&LengthScorer, &words), Some("strengths"));
    check_eq(best_word(&VowelScorer { bonus: 5 }, &words), Some("audio"));
    check_eq(best_word(&LetterScorer, &words), Some("quiz"));
    check_eq(best_word(&LengthScorer, &["ab", "cd"]), Some("ab"));
    check_eq(best_word(&LengthScorer, &[]), None);
});

test("names through the trait", || {
    check_eq(describe(&LetterScorer, "fox"), "letters: fox scores 13");
    check_eq(describe(&VowelScorer { bonus: 2 }, "tea"), "vowels: tea scores 5");
    check_eq(<LengthScorer as Scorer>::NAME, "length");
});

